def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [[bg] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != bg:
                out[r + 1][c] = grid[r][c]
    return out

