def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Connect same-color markers that lie on a diagonal in the demonstrated
    # down-right direction.
    for color in (1, 6):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for i, (r, c) in enumerate(pts):
            for rr, cc in pts[i + 1:]:
                if rr - r == cc - c:
                    for k in range(1, rr - r):
                        if grid[r + k][c + k] == 4:
                            out[r + k][c + k] = color
    return out

