def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    for color in colors - {bg}:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Continue the 45-degree diagonal joining each pair of markers, in
        # both directions, until reaching the grid boundary.
        for i, (r, c) in enumerate(pts):
            for rr, cc in pts[i + 1:]:
                dr, dc = rr-r, cc-c
                if abs(dr) == abs(dc) and dr != 0:
                    sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                    y, x = r, c
                    while 0 <= y < h and 0 <= x < w:
                        if grid[y][x] == bg:
                            out[y][x] = color
                        y -= sr; x -= sc
                    y, x = r, c
                    while 0 <= y < h and 0 <= x < w:
                        if grid[y][x] == bg:
                            out[y][x] = color
                        y += sr; x += sc
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = {v: [(r,c) for r in range(h) for c in range(w) if grid[r][c] == v]
              for v in set(v for row in grid for v in row) if v != bg}
    # Fill diagonal segments between same-colored markers.
    for color, pts in points.items():
        for i,(r,c) in enumerate(pts):
            for rr,cc in pts[i+1:]:
                dr,dc=rr-r,cc-c
                if dr and abs(dr)==abs(dc):
                    sr,sc=(1 if dr>0 else -1),(1 if dc>0 else -1)
                    for k in range(abs(dr)+1):
                        y,x=r+sr*k,c+sc*k
                        if grid[y][x]==bg: out[y][x]=color
    # A lone 6 crossed by a line of 1s draws a full opposite-slope diagonal.
    ones=points.get(1,[])
    sixes=points.get(6,[])
    for r,c in sixes:
        crossed=False
        for i,(a,b) in enumerate(ones):
            for aa,bb in ones[i+1:]:
                if abs(aa-a)==abs(bb-b) and aa!=a:
                    if (r-a)*(bb-b)==(c-b)*(aa-a): crossed=True
        if crossed:
            slope=-1
            # perpendicular to the 1-line slope
            for sr,sc in ((1,slope),(-1,-slope)):
                y,x=r,c
                while 0<=y<h and 0<=x<w:
                    if grid[y][x]==bg: out[y][x]=6
                    y+=sr;x+=sc
    return out

