        for i,(r,c) in enumerate(pts):
            for rr,cc in pts[i+1:]:
                dr,dc=rr-r,cc-c
                if dr and abs(dr)==abs(dc):
                    sr,sc=(1 if dr>0 else -1),(1 if dc>0 else -1)
                    if color==6:
                        y,x=r,c
                        while 0<=y<h and 0<=x<w:
                            if grid[y][x]==bg:out[y][x]=color
                            y+=sr;x+=sc
                    else:
                        for k in range(1,abs(dr)):
                            out[r+sr*k][c+sc*k]=color
    return out
